<?php
require_once __DIR__.'/../includes/bootstrap.php';
$id=(int)($_GET['id']??0);$stmt=$pdo->prepare("SELECT c.*,u.name instructor_name FROM courses c LEFT JOIN users u ON u.id=c.teacher_id WHERE c.id=?");$stmt->execute([$id]);$course=$stmt->fetch();if(!$course) die(t('course_not_found'));
$course=localizedCourse($course);
$less=$pdo->prepare("SELECT * FROM lessons WHERE course_id=? ORDER BY lesson_order");$less->execute([$id]);$lessons=$less->fetchAll();
$rev=$pdo->prepare("SELECT r.*,u.name FROM reviews r JOIN users u ON u.id=r.user_id WHERE r.course_id=? ORDER BY r.created_at DESC");$rev->execute([$id]);$reviews=$rev->fetchAll();
$enrolled=false;$paid=false;
if(isLoggedIn()){$x=$pdo->prepare("SELECT * FROM enrollments WHERE course_id=? AND user_id=?");$x->execute([$id,$_SESSION['user_id']]);$en=$x->fetch();$enrolled=!!$en;$paid=$en && $en['status']==='paid';}
if($_SERVER['REQUEST_METHOD']==='POST' && isLoggedIn()){
 $action=$_POST['action']??'';
 if($action==='enroll_free' && ($course['type']==='free')){$s=$pdo->prepare("INSERT IGNORE INTO enrollments(user_id,course_id,status) VALUES(?,?,?)");$s->execute([$_SESSION['user_id'],$id,'paid']);$enrolled=true;$paid=true;}
 if($action==='buy'){redirect('/women_in_tech_php/payment.php?course_id='.$id.'&lang='.urlencode($lang));}
 if($action==='review' && $enrolled){$rating=max(1,min(5,(int)$_POST['rating']));$comment=trim($_POST['comment']??'');if($comment!==''){$s=$pdo->prepare("INSERT INTO reviews(user_id,course_id,rating,comment) VALUES(?,?,?,?,?)");$s->execute([$_SESSION['user_id'],$id,$rating,$comment]);redirect("details.php?id=$id&lang=".urlencode($lang));}}
}
$pageTitle=$course[localizedColumn('title')];require __DIR__.'/../includes/header.php';?>
<section class="section"><div class="container course-detail"><div><span class="pill"><?=e($course['level'])?></span><h1><?=e($course[localizedColumn('title')])?></h1><p class="muted"><?=e($course[localizedColumn('description')])?></p><div class="card"><h2><?=t('course_overview')?></h2><p><?=e($course[localizedColumn('long_description')])?></p><h3><?=t('what_learn')?></h3><ul><li><?=t('learn_projects')?></li><li><?=t('career_skills')?></li><li><?=t('community_support')?></li></ul></div><div class="section" style="padding-bottom:0"><h2><?=t('lessons')?></h2><div class="lesson-list"><?php foreach($lessons as $i=>$l):$can=$l['is_free']||$paid;?><div class="lesson <?=$can?'':'locked'?>"><span><?=$i+1?>. <?=e($l[localizedColumn('title')])?></span><span><?=$l['is_free']?'🆓':($can?'▶️':'🔒')?></span></div><?php endforeach;?></div></div>
<div class="section"><h2><?=t('reviews')?></h2><?php if(!$reviews):?><p class="muted"><?=t('no_comments')?></p><?php endif;?><?php foreach($reviews as $r):?><div class="comment"><strong><?=e($r['name'])?> · <?=str_repeat('⭐',(int)$r['rating'])?></strong><span><?=e($r['comment'])?></span></div><?php endforeach;?><?php if($enrolled):?><form method="post" class="card" style="margin-top:20px"><input type="hidden" name="action" value="review"><div class="field"><label>Rating</label><select name="rating"><option>5</option><option>4</option><option>3</option><option>2</option><option>1</option></select></div><div class="field"><textarea name="comment" placeholder="<?=t('write_comment')?>" required></textarea></div><button class="btn"><?=t('send')?></button></form><?php endif;?></div>
</div><aside><div class="card"><div class="course-cover"><?=e($course[localizedColumn('title')])?></div><h2 class="price"><?=$course['price_iqd']?number_format((int)$course['price_iqd']).' '.t('iqd'):t('free')?></h2><p class="muted"><?=t('lessons')?>: <?=$course['lessons_count']?> · <?=t('instructor')?>: <?=e($course['instructor_name']??'WomenInTech')?></p>
<?php if(!isLoggedIn()):?><a class="btn" style="width:100%" href="/women_in_tech_php/auth/login.php?lang=<?=e($lang)?>"><?=t('login')?></a><?php elseif($course['type']==='free' && !$enrolled):?><form method="post"><input type="hidden" name="action" value="enroll_free"><button class="btn" style="width:100%"><?=t('enroll')?></button></form><?php elseif(!$paid):?><a class="btn" style="width:100%" href="/women_in_tech_php/payment.php?course_id=<?=$id?>&lang=<?=e($lang)?>"><?=t('buy_course')?></a><p class="muted" style="font-size:12px"><?=t('course_continue_note')?></p><?php else:?><a class="btn" style="width:100%" href="/women_in_tech_php/dashboard/index.php?lang=<?=e($lang)?>"><?=t('continue_learning')?></a><?php endif;?>
<hr style="border:0;border-top:1px solid #eee;margin:20px 0"><a class="btn secondary" style="width:100%" href="/women_in_tech_php/chat/chat.php?course_id=<?=$id?>&lang=<?=e($lang)?>">💬 <?=t('ask_teacher')?></a></div></aside></div></section>
<?php require __DIR__.'/../includes/footer.php'; ?>